(5029952, 733641, 94265, '<td valign="top">Kinda random, pretty cool, good colour scheme. I like it.</td>', 'Kinda random, pretty cool, good colour scheme. I like it.', '2008-10-29 00:22:46.000000', NULL, 1),
(5029958, 734077, 94265, '<td valign="top">I wanted to do origami-style with paper money for my shot but it''s too fiddly for me, I''m far too impatient. This is a really clever idea, the light and composition are really good.</td>', 'I wanted to do origami-style with paper money for my shot but it''s too fiddly for me, I''m far too impatient. This is a really clever idea, the light and composition are really good.', '2008-10-29 00:24:59.000000', NULL, 1),
(5029959, 733551, 94265, '<td valign="top">Really good focus and sharp detail on the coins, I like the composition too.</td>', 'Really good focus and sharp detail on the coins, I like the composition too.', '2008-10-29 00:25:46.000000', NULL, 1),
(5029963, 734731, 94265, '<td valign="top">Haven''t you heard that you shouldn''t put all your eggs in one basket....? Sorry, the joke had to be made, hehe. Perfect focus and great lighting, doesn''t say money to me without the title but it''s a really good quality shot.</td>', 'Haven''t you heard that you shouldn''t put all your eggs in one basket....? Sorry, the joke had to be made, hehe. Perfect focus and great lighting, doesn''t say money to me without the title but it''s a really good quality shot.', '2008-10-29 00:27:38.000000', NULL, 1),
(5029968, 734279, 94265, '<td valign="top">Excellent focus and sharpness, really great. The crop is just a tiny bit tight on either side.</td>', 'Excellent focus and sharpness, really great. The crop is just a tiny bit tight on either side.', '2008-10-29 00:29:03.000000', NULL, 1),
(5029977, 733614, 94265, '<td valign="top">I don''t quite get the egg''s significance in this but it looks pretty cool! Good focus on the shell, nice sharpness on the coins.</td>', 'I don''t quite get the egg''s significance in this but it looks pretty cool! Good focus on the shell, nice sharpness on the coins.', '2008-10-29 00:32:08.000000', NULL, 1),
