(5044568, 733219, 67697, '<td valign="top">the inverse makes this a unique looking photo in the challenge.  Cool idea.</td>', 'the inverse makes this a unique looking photo in the challenge.  Cool idea.', '2008-11-04 23:39:55.000000', NULL, 1),
(5044572, 733551, 67697, '<td valign="top">I wish I could capture motion like this.  I love how everything is frozen in space.  Very cool.</td>', 'I wish I could capture motion like this.  I love how everything is frozen in space.  Very cool.', '2008-11-04 23:40:53.000000', NULL, 1),
(5044573, 733278, 67697, '<td valign="top">I like the lighting, clarity, and range of colors.</td>', 'I like the lighting, clarity, and range of colors.', '2008-11-04 23:41:32.000000', NULL, 1),
(5044579, 734745, 67697, '<td valign="top">The background that the coin is on is a great color complement.  I like how it looks like the coin figure is gasping as if wondering what is coming next.</td>', 'The background that the coin is on is a great color complement.  I like how it looks like the coin figure is gasping as if wondering what is coming next.', '2008-11-04 23:42:39.000000', NULL, 1),
(5044586, 733214, 67697, '<td valign="top">I haven''t seen the second coin from the right yet - what is it?  I love how the reflected light is making the eyes glow.  That really caught my attention!</td>', 'I haven''t seen the second coin from the right yet - what is it?  I love how the reflected light is making the eyes glow.  That really caught my attention!', '2008-11-04 23:43:55.000000', NULL, 1),
(5044593, 734474, 67697, '<td valign="top">interesting use of origami and the light and shadow.  did you try a little darker background?  the white background kind of takes away from any potential dramatic impact.  i gave this a 6 because i like the idea and the effect.</td>', 'interesting use of origami and the light and shadow.  did you try a little darker background?  the white background kind of takes away from any potential dramatic impact.  i gave this a 6 because i like the idea and the effect.', '2008-11-04 23:47:05.000000', NULL, 1),
